import json,csv,re
from pathlib import Path
P=Path(__file__).parent
talks=[];items=[];problems=[];corrections=[]
def talk(n,date,speaker,pages,title,summary,kind='talk'):
 talks.append(dict(record=n,date=date,speaker=speaker,pages=pages,title=title,kind=kind,summary=summary))
def item(n,pages,kind,title,notes,statement,fate,refs=(),cls='E',reconstruction='',literal='correct',match='exact',verification='read the result',development='none',problem='',worth='',confidence='high',speaker=None,status=None):
 d=dict(id=f'1987-{n}.{1+sum(x["record"]==n for x in items)}',record=n,pages=pages,kind=kind,title=title,notes=notes,statement=statement,reconstruction=reconstruction,**{'class':cls},fate=fate,present_status='As of 11 November 2026: '+(status if status else ('established under the stated hypotheses.' if cls in ['A','B','E'] else 'the qualification described above remains essential.')),literal_correctness=literal,publication_match=match,verification=verification,development=development,problem=problem,worth=worth,refs=list(refs),confidence=confidence)
 if speaker:d['speaker']=speaker
 items.append(d);return d['id']
def prob(num,title,statement,occ,status,refs):
 problems.append(dict(id=f'GP-1987-{num:02}',title=title,statement=statement,occurrences=occ,status=status,status_date='2026-11',refs=refs))
def corr(page,place,reads,should,evidence,typ='faithful_error',applies='both'):
 corrections.append(dict(page=page,place=place,transcription_reads=reads,should_read=should,evidence=evidence,applies_to=applies,type=typ))
def save():
 def clean(x):
  if isinstance(x,str):return x.replace('\t'+'extquotesingle', "'")
  if isinstance(x,list):return [clean(v) for v in x]
  if isinstance(x,dict):return {k:clean(v) for k,v in x.items()}
  return x
 for name,data in [('talks',talks),('items',items),('problems',problems)]:
  (P/f'late_{name}.json').write_text(json.dumps(clean(data),ensure_ascii=False,indent=2)+'\n')
 with (P/'late_corrections.csv').open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=['page','place','transcription_reads','should_read','evidence','applies_to','type']);w.writeheader();w.writerows(corrections)

T=[
(739,'1988-03-21','M. M. Kapranov','P001444-P001445','Quivers, reflection functors, and hearts of derived categories',r'Kapranov reports Parthasarathy on derived reflection functors and on abelian hearts with equivalent bounded derived categories. The notes contrast an ordinary cokernel with the complex retaining its kernel. The final three-versus-four distinction does not identify the exact heart or algebra. The catalogue supplies the date; the local heading is undated. P001442--P001443 continue Radul and do not belong to this talk.'),
(740,'1988-03-23','A. V. Zelevinsky','P001446-P001447','Matroidal transversals and Hall\'s theorem',r'An independence example leads to Rado\textquotesingle s rank formula for a matroid induced by a relation. Hall\textquotesingle s marriage theorem is recovered from the free matroid, with an algorithmic remark and an application to simultaneous left and right coset representatives. Two type errors survive in the handwritten reduction.'),
(741,'1988-03-23','I. M. Gelfand','P001447','Famous problems as sources of mathematical theories',r'Gelfand lists the parallel postulate, classical construction problems, Fermat\textquotesingle s problem, the four-colour problem, and the Riemann hypothesis. These are historical and methodological remarks, not claims of new proofs. Faltings appears in the margin; the finiteness of rational points must not be confused with Fermat\textquotesingle s theorem.'),
(742,'1988-03-23','A. N. Rudakov','P001448','Exceptional bundles, Markov triples, and braid actions',r'Rudakov describes exceptional triples on the projective plane, their Markov ranks, and mutation. A quadric analogue involves exceptional quadruples and an unnamed Diophantine system; the missing system prevents an exact fate for the asserted converse. The higher-projective-space remark concerns mutation actions, without claiming transitivity in every dimension.'),
(743,'1988-03-23','M. M. Kapranov','P001448-P001449','Mutation of exceptional pairs',r'Kapranov explains exceptional pairs and their mutations. Gelfand relates the discussion to representation type and quiver reflections. The kernel sequence in the notes has its resulting exceptional pair in the wrong order. The remark that an unsolvable classification always has an open orbit is also too broad.'),
(744,'1988-03-23','A. A. Beilinson','P001449-P001452','Constructible sheaves, singular support, and microlocal Morse groups',r'The report, attributed to work of S. Gelfand, MacPherson and Vilonen, proceeds from constructibility to singular support, Lagrangian geometry and a Morse characterization of perversity. Several schematic assertions need the distinction between one test function and a conic neighbourhood, local and global finiteness, and Maslov-normalized Morse data. The zero section cannot simply be added over points outside the support.'),
(745,'1988-04-11','D. B. Fuchs','P001453-P001457','Reducibility and discharging in the four-colour theorem',r'Fuchs explains the Appel--Haken strategy through minimal counterexamples, reducible configurations, Kempe changes and Euler charge. Gelfand asks for a parallel program for the reducibility test and digresses on spherical functions. The notebook gives examples and incomplete discharging rules, not the full unavoidable set or a reproducible implementation.'),
(746,'1988-04-11','A. A. Beilinson','P001457-P001459','Perverse sheaves by vanishing cycles',r'The continuation defines vanishing cycles and repeats the microlocal Morse description. It poses the definite reconstruction problem for perverse sheaves from such data. The solution-complex and intersection-cohomology examples connect the discussion to the Riemann--Hilbert correspondence and intermediate extension. Later literature gives a fully faithful embedding and codimension-three extension, with explicit essential-image data still a separate problem.'),
(747,'1988-04-18','A. A. Beilinson','P001461','Semi-infinite Morse theory and relative index',r'Beilinson contrasts the finite-index Morse theory of geodesics with strongly indefinite functionals, relating the latter to Atiyah\textquotesingle s discussion of gauge theory. P001460 contains a Bourbaki reading list, not a sequence of asserted theorems. The detailed gauge-theoretic continuation occurs in record 751.'),
(748,'1988-04-18','I. M. Gelfand','P001461','Polarizations beyond the loop space',r'Gelfand connects positive and negative Fourier modes with tau-functions and semi-infinite cohomology, then suggests replacing the circle by another manifold. No elliptic operator, polarization class, or target invariant is specified for that extension.'),
(749,'1988-04-18','N. Yu. Reshetikhin','P001461-P001467','Quantum groups, braiding, and coloured link invariants',r"Reshetikhin gives the rank-one quantum enveloping algebra, coproduct and representations, then the universal R-matrix, braid actions and diagrammatic link evaluation. The core Hopf-algebra and braiding framework was public by Drinfeld's 1986 congress report. Reshetikhin's LOMI preprints E-4-87 and E-17-87 closely match the talk, but the scanned editions bear a 1988 imprint; a 1987 series number and recommendation are not an independently established circulation date. Antipode and normalization formulas in the notes need correction; generic deformation parameters and framing conventions are indispensable. The assertion that the rank-one invariants suffice has no stated separation criterion."),
(750,'1988-04-25','A. G. Ushveridze','P001468-P001472','Riccati equations and quasi-exact solvability',r'The talk constructs finite families of Riccati solutions from poles satisfying Bethe-type equations, with rational, trigonometric and elliptic addition laws. It discusses electrostatics, common eigenspaces and conversion to Schrodinger equations. The author\textquotesingle s 1989 review is a close primary source. Two addition-law constants and the root equations in the manuscript require explicit repair.'),
(751,'1988-04-25','A. A. Beilinson','P001472-P001477','Morse theory, Chern--Simons theory, and three-manifold invariants',r'Beilinson reports Atiyah\textquotesingle s picture linking the Morse complex, flat connections, spectral flow, Lagrangian intersections and four-dimensional instantons. The false equivalence between ordinary and twisted first-cohomology vanishing is corrected separately. The scan at P001478 starts a new session dated 12 September 1988, and P001479 continues that next academic year; neither belongs to this record.')]
for t in T:talk(*t)

item(739,'P001444','definition','Representations of an acyclic quiver',r'A quiver is called a directed graph without cycles; \(M(\Lambda,\Omega)\) is its representation category.',r'For a finite quiver \(Q=(Q_0,Q_1)\) with no oriented cycles over a field \(k\), let \(\operatorname{rep}_kQ\) consist of finite-dimensional vertex spaces and linear arrow maps. It is an abelian hereditary category, equivalent to finite-dimensional modules over \(kQ\).',r'This is the framework of \citet[\S1]{bernsteingelfandponomarev1973coxeter}; the derived-category report uses it in \citet[\S1]{parthasarathy1988tstructures}.', ['bernsteingelfandponomarev1973coxeter','parthasarathy1988tstructures'],reconstruction='Finiteness, the coefficient field, and oriented rather than undirected cycles are made explicit.',literal='correct with missing hypotheses')
item(739,'P001444','claim','Orientation independence and its graph hypothesis',r'The lemma says \(\mathcal D(\Lambda,\Omega_1)\simeq\mathcal D(\Lambda,\Omega_2)\) for different orientations, with reflections as proof.',r'A reflection at a source or sink induces an equivalence of bounded derived categories. Hence orientations joined by such reflections have equivalent categories; in particular this holds for any two orientations of a finite tree, including every Dynkin tree.',r'\citet[Propositions~1.4 and~1.6]{parthasarathy1988tstructures} constructs the derived reflection equivalences from BGP functors. An unrestricted assertion for all acyclic orientations of an arbitrary graph is not supplied by this argument.', ['parthasarathy1988tstructures','bernsteingelfandponomarev1973coxeter'],reconstruction='The tree or reflection-equivalence hypothesis is essential; the drawing alone does not establish it.',literal='correct with missing hypotheses',match='partial',development='annotated',status='derived reflection invariance is established; the notebook\textquotesingle s unrestricted orientation wording should not be used as a theorem.')
a=item(739,'P001444-P001445','problem','Hearts with the same derived category',r'Find abelian subcategories \(\mathcal A\subset\mathcal D\) with \(\mathcal D^\ell(\mathcal A)=\mathcal D\); the notes say all are found and characterized by Dynkin graphs.',r'For a finite acyclic quiver \(Q\), describe bounded t-structures on \(D^b(\operatorname{rep}_kQ)\) whose heart \(\mathcal A\) has realization functor \(D^b(\mathcal A)\to D^b(\operatorname{rep}_kQ)\) an equivalence, subject to the finite-length and projective-generation conditions of the classification used.',r'\citet[Theorems~3.3, 7.1 and~8.5]{parthasarathy1988tstructures} gives the realization criterion, the relation to iterated tilted algebras, and the Dynkin completeness result. The manuscript was received 15 February 1988, revised 13 May, and published in December; the seminar already names it. The blanket sentence is broader than those results.', ['parthasarathy1988tstructures'],reconstruction='The superscript is read as bounded derived category, and abelian subcategory is interpreted as a heart. The stated finiteness conditions prevent a claim about arbitrary embedded abelian categories.',literal='correct with missing hypotheses',match='partial',problem='GP-1987-41',confidence='medium',status='the identified finite-type/iterated-tilting classification is established; an unrestricted classification is not asserted.')
prob(41,'Hearts realizing the derived category of a quiver',items[-1]['statement'],[a],r'The finite-type formulation reported here is treated in Parthasarathy\textquotesingle s 1988 paper; arbitrary abelian subcategories are outside the identified theorem.',['parthasarathy1988tstructures'])
item(739,'P001444-P001445','construction','A source reflection retains a two-term complex',r'At a source \(\alpha\), replace \(V_\alpha\) by the cokernel of \(V_\alpha\to\bigoplus_{\alpha\to\beta}V_\beta\); vectors killed by every arrow are lost, so retain the map as a complex.',r'The ordinary reflection uses that cokernel and reverses the incident arrows. Its total derived functor uses the two-term complex, with a degree convention fixed once, and preserves the kernel information. This gives the source reflection equivalence.',r'BGP\textquotesingle s source/sink functors appear in \citet[\S1]{bernsteingelfandponomarev1973coxeter}; the derived construction is explicit in \citet[\S1, Proposition~1.6]{parthasarathy1988tstructures}.', ['bernsteingelfandponomarev1973coxeter','parthasarathy1988tstructures'],reconstruction='The vertex is required to be a source and the cone shift is conventional.',literal='correct with missing hypotheses')
item(739,'P001444','remark','Derived categories as a language for projective bundles',r'Gelfand says classification of vector bundles on \(\mathbb{CP}^n\) can only be done in the language of derived categories.',r'An established precise tool is the exceptional collection \((\mathcal O,\mathcal O(1),\ldots,\mathcal O(n))\) on \(\mathbb P^n\) and the resulting resolution of coherent sheaves by explicit complexes. This does not prove the literal exclusivity of a mathematical language or classify all bundles.',r'\citet{beilinson1978coherent} supplies the relevant pre-1988 construction. The word ``only'' is methodological emphasis rather than a theorem.', ['beilinson1978coherent'],reconstruction='The resolution is an illustrative reconstruction of the method, not an assertion that Gelfand stated a classification theorem.',literal='not determinable',match='thematic only',verification='indirect',speaker='I. M. Gelfand',confidence='medium')
item(739,'P001445','remark','The unexplained three-versus-four distinction',r'Parthasarathy is said to answer when the derived category coincides with this one: for three, but not for four.',r'No definite equivalence assertion is reconstructible: the category being compared and the meaning of three or four are not specified beyond the adjacent star diagram.',r'The explicit source-star construction and the Dynkin classification in \citet[\S\S1,8]{parthasarathy1988tstructures} explain possible background, but do not license an exact numerical theorem from this sentence.', ['parthasarathy1988tstructures'],cls='F',literal='not determinable',match='thematic only',confidence='low',status='unidentified at the level of an exact mathematical statement.')
save()

item(740,'P001446','definition','Linear independence as a matroid',r'Gelfand gives linearly independent systems of vectors as the example of a matroid.',r'For a finite indexed family \((v_e)_{e\in E}\) in a vector space, let \(\mathcal I=\{I\subset E:(v_e)_{e\in I}\text{ is linearly independent}\}\). Heredity and the exchange axiom make \((E,\mathcal I)\) a matroid.',r'This is the elementary representable-matroid example in \citet[opening definitions]{oxleybriefly}. Compare the matroid/lattice occurrence 1985-658.12; no new problem is posed here.', ['oxleybriefly'],verification='indirect',speaker='I. M. Gelfand')
item(740,'P001446','theorem','Rado transversals and the induced rank formula',r'For a relation \(\varphi\subset M_1\times M_2\), the asserted rank is \(r_2(A)=\min_{B\subset A}(r_1(\varphi(B))+|A-B|)\).',r'Let \(M_1\) be a finite matroid and \(M_2\) finite. A subset \(I\subset M_2\) is independent when it admits distinct representatives in \(M_1\), related to its elements by \(\varphi\), that form an independent set of the first matroid. These sets form a matroid, and the displayed minimum is its rank on \(A\).',r'The independence-transversal theorem is \citet{rado1942independence}; Hall\textquotesingle s special case predates it. The publisher-deposited Crossref metadata for Rado were opened and checked; the full original theorem was not successfully opened in this run.', ['rado1942independence','hall1935representatives'],literal='correct with missing hypotheses',verification='publisher metadata checked',confidence='medium',reconstruction='Finite ground sets and the independent-transversal definition are supplied explicitly.')
item(740,'P001446-P001447','theorem','Hall\'s marriage theorem and the free-matroid reduction',r'The union condition for sets \(B(n)\subset M\) yields an injection \(f:N\to M\); the notes write \(f(n)\subset B(n)\) and declare all subsets of \(N\) independent.',r'For finite \(N\), an injection satisfying \(f(n)\in B(n)\) exists iff \(|\bigcup_{n\in K}B(n)|\geq|K|\) for every \(K\subset N\). To derive this from Rado with representatives in \(M\), use the free matroid on \(M\), whose rank is cardinality.',r'\citet[Theorem~1, pp.~27--29]{hall1935representatives} proves precisely this condition; the paper was received and read in April 1934 and published in 1935.', ['hall1935representatives'],literal='false as written',development='annotated',reconstruction='Membership replaces subset inclusion, and the free matroid belongs on the representative ground set \(M\).')
item(740,'P001447','method','An algorithmic proof of the marriage theorem',r'There is a proof containing an algorithm.',r'For a finite bipartite graph, start with a matching and repeatedly augment along alternating paths. If no augmenting path exists while a left vertex is unmatched, its alternating reachable sets violate Hall\textquotesingle s condition. Thus the procedure finds a complete left matching under that condition.',r'\citet[proof of Theorem~1]{hall1935representatives} gives a constructive replacement argument. The augmenting-path formulation is an explicit modern reconstruction of the terse algorithmic remark.', ['hall1935representatives'],match='partial',reconstruction='The notes do not name a running time or a particular implementation; no algorithmic novelty is inferred.')
item(740,'P001447','theorem','A common system of left and right coset representatives',r'A finite subgroup has representatives that work simultaneously for its left and right cosets; the statement is attributed to Birkhoff.',r'If \(H\leq G\) and \(G\) is finite, there is a set meeting each left coset and each right coset of \(H\) once. More generally finite \(H\) admits such a transversal in arbitrary \(G\), by applying the finite equal-block matching argument within each double coset and choosing these transversals.',r'\citet[Theorem~3 and its equal-size corollary, pp.~29--30]{hall1935representatives} supplies the partition theorem; its application to cosets is immediate. Hall credits the equal-block result to Konig, so the notebook\textquotesingle s attribution is not independently confirmed.', ['hall1935representatives'],reconstruction='For infinite \(G\), each double coset has equally many left and right cosets because \(H\) is finite; a choice of the finite matchings is used.',literal='correct with missing hypotheses',match='partial')
corr('P001447','Hall conclusion',r'f(n)\subset B(n)',r'f(n)\in B(n)','The manuscript and both transcriptions use a subset sign although f(n) is a single representative; Hall 1935 Theorem 1 supplies the mathematical emendation.')
corr('P001447','Reduction to Rado','all subsets of N are independent','use the free matroid on M','Representatives belong to M, whereas N indexes the sets B(n); this is a faithful error in the notebook, not a translation discrepancy.')
save()

item(741,'P001447','remark','The parallel postulate and non-Euclidean models',r'The parallel axiom is listed as a seemingly fruitless problem that produced non-Euclidean geometry.',r'Models of hyperbolic geometry satisfy the other standard incidence/congruence axioms but not Euclid\textquotesingle s parallel axiom; relative to the consistency of the background geometry, the axiom cannot be deduced from those remaining axioms.',r'\citet{beltrami1869interpretation} is the opened 1869 French publication of Beltrami\textquotesingle s 1868 interpretation. This supports the mathematical endpoint, not an exhaustive causal history.', ['beltrami1869interpretation'],verification='publisher metadata checked',match='partial',reconstruction='The formal independence statement is relative to an axiom system and consistency assumption, neither specified in the remark.')
item(741,'P001447','remark','Classical construction impossibilities',r'Angle trisection and circle quadrature are linked with the development of Galois theory.',r'With an unmarked straightedge and compass, an arbitrary given angle cannot be trisected, and a square of the same area as a given circle cannot be constructed. The first follows from a cubic obstruction, for example trisection of \(60^\circ\); the second follows from the transcendence of \(\pi\).',r'\citet[\S1 and the applications]{wantzel1837constructions} treats algebraic constructibility and trisection. The two impossibilities have different proofs; quadrature is not a consequence solely of finite Galois theory. The opened publisher record verifies Lindemann\textquotesingle s 1882 paper; its original proof was not read in this run.', ['wantzel1837constructions','lindemann1882pi'],literal='correct with missing hypotheses',match='partial',reconstruction='The allowed instruments and the general rather than every-angle quantifier are supplied.',confidence='medium')
a=item(741,'P001447','remark','Fermat\'s equation and the later modularity proof',r'Fermat\textquotesingle s problem is linked to Kummer\textquotesingle s ideals and algebraic geometry; Faltings appears in a marginal annotation.',r'For every integer \(n>2\), there are no positive integers \(a,b,c\) with \(a^n+b^n=c^n\). Finiteness of rational points on a fixed genus-greater-than-one curve does not by itself prove this nonexistence statement.',r'\citet{wiles1995modular} establishes the semistable modularity theorem underlying the proof; the final argument was published in 1995 after the 1993 announcement and the repair with Taylor. The opened Annals record confirms publication, but the full proof was not read in this run.', ['wiles1995modular'],cls='B',match='partial',verification='publisher metadata checked',problem='GP-1987-42',reconstruction='The exact Fermat statement is the standard meaning of the named problem; the marginal Faltings attribution is not turned into a claim of a solution.',status='Fermat\textquotesingle s last theorem is proved; the historical chain in the notes remains a compressed motivation.')
prob(42,'Fermat\'s last theorem',items[-1]['statement'],[a],r'Settled by the modularity method published in 1995; the 1988 marginal mention of Faltings did not settle the equation.',['wiles1995modular'])
a=item(741,'P001447','remark','Four colours and computer-assisted proof',r'The four-colour problem is connected with computer mathematics.',r'Every finite loopless planar graph admits a proper vertex colouring with at most four colours. The 1976 Appel--Haken proof combined unavoidable configurations with certified reducibility computations.',r'The reducibility component was published as \citet{appelhakenkoch1977reducibility}; \citet[\S\S2--3]{gonthier2005fourcolour} later formalized the complete theorem. Fuchs returns to the proof in record 745.', ['appelhakenkoch1977reducibility','gonthier2005fourcolour'],problem='GP-1987-43',match='partial')
prob(43,'Four-colour theorem and reducibility',r'Does every finite loopless planar graph admit a proper four-colouring?',[a],r'Settled by Appel and Haken in 1976, published in 1977; a complete formal proof was subsequently constructed by Gonthier.',['appelhakenkoch1977reducibility','gonthier2005fourcolour'])
a=item(741,'P001447','conjecture','The Riemann hypothesis',r'The Riemann hypothesis is the fifth named example; no proof or strengthened formulation follows.',r'Every zero \(\rho\) of the analytically continued Riemann zeta function with \(0<\Re\rho<1\) satisfies \(\Re\rho=1/2\).',r'The Clay Mathematics Institute\textquotesingle s current official problem page, \citet{clay2026riemann}, still labels the problem unsolved. No narrower new question or mechanism is present in these notes.', ['clay2026riemann'],cls='C',problem='GP-1987-44',worth='The famous conjecture is worth research in general, but this occurrence offers no bounded route for a new contribution in the present chapter.',status='open; no seminar-specific partial result is claimed.')
prob(44,'Riemann hypothesis',items[-1]['statement'],[a],r'Open as of 11 November 2026, as confirmed by the official Clay problem page.',['clay2026riemann'])
save()

item(742,'P001448','definition','Exceptional bundles and ordered exceptional collections',r'For bundles \(E_1,E_2,E_3\) on \(\mathbb P^2\), the notes impose scalar endomorphisms, vanishing positive self-Ext, and backward Ext vanishing.',r'An object \(E\in D^b(\operatorname{Coh}X)\) is exceptional when \(\operatorname{Hom}(E,E)=k\) and \(\operatorname{Ext}^p(E,E)=0\) for \(p\ne0\). An ordered exceptional collection satisfies \(\operatorname{Ext}^p(E_j,E_i)=0\) for every \(p\) and \(j>i\). Here the objects are algebraic vector bundles on \(\mathbb P^2\).',r'\citet[\S1]{rudakov1988markov} states the bundle framework, already developed by the time of the talk. The corresponding 1987 projective-space paper is \citet{gorodentsevrudakov1987exceptional}.', ['rudakov1988markov','gorodentsevrudakov1987exceptional'],reconstruction='The general derived definition includes all integer shifts; for vector bundles on the plane only Ext degrees 0,1,2 can occur.')
item(742,'P001448','theorem','Exceptional ranks satisfy the Markov equation',r'The ranks \(x_1,x_2,x_3\) of the exceptional triple satisfy \(x_1^2+x_2^2+x_3^2=3x_1x_2x_3\).',r'For a full exceptional triple of vector bundles on \(\mathbb P^2\), its positive ranks form a positive integer solution of the Markov equation.',r'\citet[Theorem~3.2]{rudakov1988markov} gives the rank identity. The Russian original appeared in 1988, volume 52, issue 1; the English translation in 1989. Its submission was in April 1986.', ['rudakov1988markov'],literal='correct with missing hypotheses',reconstruction='Fullness and positive ranks are stated explicitly; this is not a rank equation for arbitrary triples of exceptional bundles.')
item(742,'P001448','theorem','Realization of positive Markov triples by bundles',r'Conversely, the notes say every integer solution is obtained.',r'Every positive integer Markov triple is realized by the ranks of an exceptional triple of bundles on \(\mathbb P^2\), obtained from the standard triple by the appropriate mutations and ordering conventions. Zero or negative integral solutions are not positive bundle ranks.',r'\citet[Introduction and Theorem~4.2]{rudakov1988markov} constructs the Markov tree of adjacent exceptional bundles. This does not assert the separate Markov uniqueness conjecture that a largest entry determines the triple.', ['rudakov1988markov'],literal='correct with missing hypotheses',development='annotated',reconstruction='The word integer is restricted to positive integer, as required by ranks.')
item(742,'P001448','construction','Mutation and the braid action on the plane',r'The braid group acts on exceptional triples, transitively in the plane case.',r'Left and right mutations of adjacent exceptional objects obey the braid relation and act on full exceptional collections. For the plane, the bundle/helix formulation produces the exceptional triples from a standard helix, with the usual shifts and simultaneous line-bundle twists accounted for.',r'\citet{gorodentsevrudakov1987exceptional} is the 1987 projective-space source; \citet[\S\S3--4]{rudakov1988markov} gives the explicit plane reconstruction corresponding to Markov moves.', ['gorodentsevrudakov1987exceptional','rudakov1988markov'],literal='correct with missing hypotheses',match='partial',reconstruction='The action is naturally on derived exceptional collections; a statement restricted to bundles requires the helix conventions, which the notes suppress.',confidence='medium')
item(742,'P001448','claim','Exceptional quadruples on a quadric',r'For \(\mathbb P^1\times\mathbb P^1\), exceptional quadruples also have a braid action and satisfy a more complicated Diophantine system.',r'On the smooth quadric surface, the four line bundles \(\mathcal O,\mathcal O(1,0),\mathcal O(0,1),\mathcal O(1,1)\) generate a standard helix. Mutations construct other helices; every helix and every exceptional bundle is constructible in Rudakov\textquotesingle s precise sense.',r'\citet[Theorems~7.1 and~10.1]{rudakov1988quadric} proves these construction results in the Russian paper published in issue 4 of 1988, translated in 1989. The English original received-date line reads 6 July 1986. This is a precise later result, not identification of an omitted numerical system.', ['rudakov1988quadric'],cls='A',literal='correct with missing hypotheses',match='partial',reconstruction='The standard helix and the exact later theorems are supplied as a bounded publication match; they do not reconstruct all numerical equations in the notebook.')
item(742,'P001448','question','The unspecified converse for quadric numerical data',r'The notes say it has not been proved that all solutions of the quadric system arise from exceptional quadruples.',r'An exact arithmetic realization question cannot be recovered, because neither the system nor its positivity, integrality and Chern-class restrictions is written.',r'\citet[\S\S5--7 and closing remark]{rudakov1988quadric} distinguishes helix construction, symmetric numerical equations, and a question about extending exceptional pairs. None can be silently substituted for the unnamed system here.', ['rudakov1988quadric'],cls='F',literal='not determinable',match='thematic only',confidence='low',status='the exact notebook question is unidentified; it is not indexed as an open numerical problem.')
item(742,'P001448','construction','Mutation of collections on higher projective spaces',r'For \(\mathbb P^n\), take \(n+1\) bundles with the same exceptional conditions; a braid group again acts.',r'Mutations act on ordered full exceptional collections of length \(n+1\) in \(D^b(\operatorname{Coh}\mathbb P^n)\). The standard line-bundle collection is an example. This statement does not claim transitivity on all collections or classification of all vector bundles when \(n>2\).',r'The pre-talk source is \citet{gorodentsevrudakov1987exceptional}; its bibliographic record was opened. The construction is consistent with the explicit mutation formalism in \citet[\S2]{rudakov1988quadric}.', ['gorodentsevrudakov1987exceptional','rudakov1988quadric'],literal='correct with missing hypotheses',match='partial')
corr('P001448','Markov converse','all integer solutions','all positive integer solutions','Ranks of nonzero vector bundles are positive; Rudakov 1988, Introduction and Theorem 4.2, treats the positive Markov tree.')
save()

item(743,'P001448','remark','Finite, tame, and wild representation problems',r'Gelfand distinguishes no parameters, one parameter, and at least two parameters, comparing the last with classifying pairs of matrices.',r'For a fixed finite-dimensional algebra over an algebraically closed field, finite representation type means finitely many indecomposable isomorphism classes; tame type permits finitely many one-parameter families in each dimension, with finitely many exceptions; wildness means that the problem of modules over the free algebra in two generators embeds in the representation problem. A raw count of parameters does not define these alternatives.',r'For quivers, the finite/Dynkin and extended-Dynkin examples already occur in 1972-277.8 and 1972-278.9. \citet{bernsteingelfandponomarev1973coxeter} supplies the finite-type setting. The remark is not a proof of a general dichotomy theorem.', ['bernsteingelfandponomarev1973coxeter'],literal='correct with missing hypotheses',match='thematic only',speaker='I. M. Gelfand',reconstruction='The standard representation-theoretic meanings replace the informal parameter count.',confidence='medium')
item(743,'P001448','claim','An open orbit is not automatic in a wild problem',r'Gelfand says an unsolvable classification always contains a solvable part, adding an open orbit.',r'Existence of a dense open orbit is a separate geometric condition. In simultaneous conjugation of pairs of \(n\times n\) complex matrices, the invariant \(\operatorname{tr}(A)\) varies, so no orbit can be dense in the full affine space of pairs. This already refutes an unconditional open-orbit assertion.',r'This is an elementary editorial check: a polynomial invariant is constant on an orbit and its closure. No external classification theorem is needed. The BGP finite-type examples give context only.', ['bernsteingelfandponomarev1973coxeter'],literal='false as written',match='thematic only',verification='indirect',speaker='I. M. Gelfand',development='annotated',reconstruction='The text is read literally as claiming an open orbit in the original representation space; a more restricted stratum could behave differently.',status='false without a specified stratum or additional hypotheses.')
item(743,'P001449','claim','Self-Ext vanishing and infinitesimal rigidity',r'\(\operatorname{Ext}^1(E,E)=0\) is interpreted as rigidity of a vector bundle.',r'For a vector bundle on a proper scheme over a field, first-order deformations over the dual numbers are parametrized by \(\operatorname{Ext}^1(E,E)\). Its vanishing implies infinitesimal rigidity; the stronger assertion of a unique global isomorphism class does not follow.',r'The deformation-free exceptional-bundle setting is explicit in \citet[Introduction and \S1]{rudakov1988markov}.', ['rudakov1988markov'],literal='correct with missing hypotheses',reconstruction='The meaning of rigidity is restricted to infinitesimal deformations, with the usual fixed base and deformation functor.')
item(743,'P001449','definition','Exceptional pairs require exceptional individual objects',r'A pair is called exceptional if \(\operatorname{Ext}^j(F,E)=0\); the individual conditions are not repeated.',r'An exceptional pair \((E,F)\) consists of two exceptional objects and has \(\operatorname{RHom}(F,E)=0\). Backward orthogonality alone is insufficient to imply either object is exceptional.',r'\citet[\S2]{rudakov1988quadric} gives the admissible/exceptional pair formalism; the earlier individual conditions on P001448 provide likely context, but must be restored when this item is read alone.', ['rudakov1988quadric'],literal='correct with missing hypotheses',reconstruction='The individual scalar-endomorphism and self-Ext conditions are explicitly reinstated.')
item(743,'P001449','construction','The kernel mutation has the wrong pair order in the notes',r'The sequence \(0\to R\to E\otimes\operatorname{Hom}(E,F)\to F\) is followed by the assertion that \((F,R)\) is exceptional.',r'For an exceptional pair with \(\operatorname{RHom}(E,F)\) concentrated in degree zero and surjective evaluation, the kernel \(R\) gives the left mutation, with the appropriate shift convention. The resulting exceptional pair is \((R,E)\), not \((F,R)\). In general use the distinguished triangle \(L_EF\to\operatorname{RHom}(E,F)\otimes E\to F\to L_EF[1]\).',r'\citet[\S2]{rudakov1988quadric} gives left/right mutation. A direct check on \(\mathbb P^1\), \(E=\mathcal O\), \(F=\mathcal O(1)\), has \(R=\mathcal O(-1)\) and \(\operatorname{Hom}(R,F)\ne0\), contradicting the displayed pair in the notebook.', ['rudakov1988quadric'],literal='false as written',development='annotated',reconstruction='Surjectivity and the strong-pair hypothesis are needed for a kernel bundle; the triangle supplies the general derived construction.',status='the standard mutation is established; the literal order in the source is false.')
item(743,'P001449','construction','Braid relations and the quiver-reflection analogy',r'Mutation gives the braid-group action; Gelfand recalls BGP and recommends studying quiver representations and derived categories for spectral theory.',r'Adjacent mutations on exceptional collections satisfy \(\sigma_i\sigma_{i+1}\sigma_i=\sigma_{i+1}\sigma_i\sigma_{i+1}\), with distant generators commuting. BGP reflections provide a related, but differently defined, transformation of quiver representations.',r'\citet[\S2, Proposition~2.1 and the reconstruction formalism]{rudakov1988quadric} treats mutations; \citet[\S1]{bernsteingelfandponomarev1973coxeter} is the earlier reflection construction. The recommendation for spectral theory states no further definite theorem.', ['rudakov1988quadric','bernsteingelfandponomarev1973coxeter'],match='partial',reconstruction='The braid relation is stated for the derived mutation operations; the analogy is not an identification of the two actions.')
corr('P001449','Kernel mutation result',r'(F,R) is exceptional',r'(R,E) is exceptional, under the kernel hypotheses','The scan clearly writes (F,R). On P1 the evaluation O^2 to O(1) has kernel O(-1); Hom(O(-1),O(1)) is nonzero, disproving the printed order.')
corr('P001448','Open-orbit remark','an unsolvable classification always has a solvable part (open orbit)','an open orbit requires additional hypotheses or restriction to a specified stratum','Simultaneous conjugation of matrix pairs has the varying polynomial invariant tr(A), so no orbit is dense in the full representation space.')
save()

item(744,'P001449','question','Gelfand\'s geometric configuration question',r'Before the perverse-sheaf exposition, Gelfand asks about regions/configurations and Siegel domains, with a drawing in the real projective plane.',r'The invariant, parameter space, equivalence relation and intended assertion are not specified well enough to formulate a definite classification problem.',r'The neighbouring microlocal discussion does not supply the missing data. No exact publication is identified, and no open problem is inferred from a topic-level resemblance.',[],cls='F',literal='not determinable',match='none found',verification='unresolved lead',speaker='I. M. Gelfand',confidence='low',status='unidentified as a mathematical question.')
item(744,'P001450','definition','Constructible sheaves and complexes',r'A sheaf is locally constant of finite rank on each stratum; for a complex the condition is on its cohomology sheaves, not on its terms.',r'For a complex algebraic variety with a finite algebraic Whitney stratification \(\mathcal S\), \(D^b_{\mathcal S}(X;k)\) consists of bounded sheaf complexes whose cohomology restricts to finite-rank local systems on every stratum. Analytic versions use locally finite stratifications.',r'\citet[Chapter~8]{kashiwaraschapira1985microlocal} treats the constructibility conditions. The notebook correctly distinguishes cohomological constructibility from a particular complex of representatives.', ['kashiwaraschapira1985microlocal'],literal='correct with missing hypotheses',reconstruction='Boundedness, coefficients, Whitney regularity and finiteness conventions are supplied.')
item(744,'P001450','definition','Singular support requires uniform local tests',r'A nonzero covector is excluded from \(SS(\mathcal F)\) when a relative cohomology group for a function with that differential vanishes; the notes say the choice of function does not matter.',r'For a bounded constructible complex on a real manifold, \((x,\xi)\notin SS(F)\) means there is an open conic neighbourhood on which all local cohomology tests \((R\Gamma_{\{\phi\geq\phi(y)\}}F)_y\) vanish whenever \((y,d\phi_y)\) lies in that neighbourhood. Holomorphic Morse tests describe the corresponding complex-constructible microsupport, with their normalizations.',r'The uniform-neighbourhood condition is in \citet[Definition~0.1 and \S3.1]{kashiwaraschapira1985microlocal}. Vanishing for a single arbitrary chosen function is not the complete definition.', ['kashiwaraschapira1985microlocal'],literal='correct with missing hypotheses',development='annotated',reconstruction='The precise real-test definition is supplied to avoid interpreting a schematic single-function test as an invariant definition.')
item(744,'P001450','claim','The zero-section part of singular support',r'If the complex is nonzero, the entire zero section is added; an acyclic complex has empty singular support.',r'One has \(SS(F)\cap T_X^*X=\operatorname{supp}(F)\), where the right side is embedded as zero covectors. Thus \(SS(0)=\varnothing\), but a nonzero skyscraper sheaf does not contain zero covectors over other points.',r'\citet[\S3.1, basic properties of microsupport]{kashiwaraschapira1985microlocal} gives the support relation. The skyscraper example on P001452 itself detects the error.', ['kashiwaraschapira1985microlocal'],literal='false as written',development='annotated',status='the support-restricted statement is standard; the unconditional addition of the zero section is false.')
item(744,'P001451','theorem','Complex constructibility gives a conic Lagrangian support',r'\(SS(F)\) is an analytic conic Lagrangian set with finitely many irreducible components; ideal involutivity is presented as equivalent.',r'For complex-constructible \(F\), its microsupport, identified with the complex cotangent bundle, is a closed complex-conic Lagrangian analytic subset. Components are locally finite; global finiteness follows in the finite algebraic setting. Involutivity of the ideal gives coisotropicity, and is equivalent to the Lagrangian condition only with the half-dimensional hypothesis.',r'\citet[Theorem~6.4.1 and Chapter~8]{kashiwaraschapira1985microlocal} supplies involutivity and the constructible Lagrangian characterization.', ['kashiwaraschapira1985microlocal'],literal='correct with missing hypotheses',reconstruction='Complex constructibility and the dimension/finiteness qualifications are made explicit.',development='annotated')
item(744,'P001451','theorem','Irreducible conic Lagrangians are conormal closures',r'An irreducible conic Lagrangian \(Y\subset T^*X\) is \(N^*Z\) for \(Z=\pi(Y)\), with closure over the smooth locus understood.',r'In the algebraic setting, a closed irreducible conic Lagrangian subset is the closure of \(T^*_{Z_{\mathrm{sm}}}X\) for the irreducible subvariety \(Z=\overline{\pi(Y)}\). The analytic assertion is local. This follows by annihilating tangent vectors to a generic smooth image under the canonical symplectic form and comparing dimensions.',r'This is the conormal geometry underlying \citet[Chapter~8]{kashiwaraschapira1985microlocal}. The argument and the closure conventions are elementary reconstruction of the lemma as stated.', ['kashiwaraschapira1985microlocal'],literal='correct with missing hypotheses',match='partial',reconstruction='Closedness, algebraic/local analytic context and closure of the image are specified.')
item(744,'P001451','definition','Morse transversality to a singular support',r'The graph of \(df\) must meet \(Y\) only at smooth points and transversely; examples are the zero section and a smooth conormal.',r'For a holomorphic function \(f\) and conic Lagrangian \(Y\), a microlocal Morse point is a transverse intersection of \(\Gamma_{df}\) with \(Y_{\mathrm{sm}}\), away from the singular part of \(Y\). For \(Y=T_X^*X\) this is an ordinary nondegenerate critical point; for \(Y=T_Z^*X\) with smooth \(Z\), it is a nondegenerate critical point of \(f|_Z\).',r'This is the test-function construction used in \citet[Introduction and \S1]{gelfandmacphersonvilonen2005microlocal}, building on the earlier microlocal theory. The crossed-out extra demand \(df\ne0\) is not part of the general conormal criterion.', ['gelfandmacphersonvilonen2005microlocal','kashiwaraschapira1985microlocal'],literal='correct',reconstruction='The criterion is local at an isolated transverse intersection, not a demand that a global function exist with every required property.')
item(744,'P001452','definition','Perversity detected by Morse groups',r'All Morse relative hypercohomology groups must occur in degree zero; a parenthetical remark instead says first degree.',r'With the convention that \(k_X[\dim_{\mathbb C}X]\) is perverse, a constructible bounded complex is perverse exactly when its normalized local Morse groups are concentrated in degree zero. For an isolated Morse test, these can be represented by \(\mathbb H^j(B,B\cap f^{-1}(\varepsilon);F)\), after fixing the vanishing-cycle shift convention.',r'\citet[Theorem~9.5.2 and Introduction]{kashiwaraschapira1985microlocal} gives the microlocal characterization. The degree-one parenthesis can reflect the unshifted vanishing-cycle cone, and cannot coexist literally with degree zero without specifying the shift.', ['kashiwaraschapira1985microlocal'],literal='correct with missing hypotheses',development='annotated',reconstruction='The normalized Morse functor rather than an unlabelled cone fixes the degree convention.')
item(744,'P001452','construction','Basic perverse sheaves and the closed-embedding hypothesis',r'Examples are a skyscraper, \(\mathbb C_X[n]\), and \(\mathbb C_Z[\dim Z]\) extended by zero from a smooth subset, or an intersection-cohomology complex.',r'A finite-dimensional skyscraper is perverse. On a smooth complex \(n\)-fold a local system shifted by \(n\) is perverse. For a closed smooth embedding \(i:Z\hookrightarrow X\), \(i_*L[\dim Z]\) is perverse. For an arbitrary open or locally closed embedding, ordinary extension by zero need not be perverse; intermediate extension is the appropriate canonical construction.',r'\citet[Theorem~9.5.2]{kashiwaraschapira1985microlocal} gives the perverse framework, and \citet{goreskymacpherson1983intersection} is the intersection-cohomology source.', ['kashiwaraschapira1985microlocal','goreskymacpherson1983intersection'],literal='correct with missing hypotheses',match='partial',reconstruction='Closedness is restored to the zero-extension example; the singular case uses intersection cohomology rather than a constant sheaf.')
item(744,'P001452','remark','Singular support does not canonically recover every stratum',r'An explicitly approximate remark identifies strata with projections of irreducible components of \(SS(F)\).',r'The projections recover certain closed singular-support loci, not a unique stratification. A compatible Whitney stratification may be refined without changing \(F\) or \(SS(F)\); even the constant sheaf admits many such refinements.',r'\citet[Chapter~8]{kashiwaraschapira1985microlocal} relates constructibility to unions of conormals, which is weaker than a unique reconstruction of the chosen strata.', ['kashiwaraschapira1985microlocal'],literal='false as written',match='partial',development='annotated',reconstruction='The notebook already flags the assertion as approximate; its strongest literal interpretation is rejected.',status='only the conormal-support relation is valid; no canonical full stratification follows.')
item(744,'P001452','construction','Morse groups form a microlocal local system with a twist',r'At a smooth covector \(z\), define \(\Phi(F)_z=H^0(U,f^{-1}(\varepsilon);F)\) for \(df=z\), claiming no dependence on \(f\).',r'On the smooth locus of a fixed singular support, normalized Morse data vary locally constantly after accounting for the Maslov/orientation data of the test-function Hessian. The natural object is a twisted local system (or a local system on the appropriate bundle of Morse data), not canonically an untwisted local system from the covector alone.',r'\citet[\S1, the bundle of test Lagrangians and Maslov data]{gelfandmacphersonvilonen2005microlocal} makes the suppressed structure explicit. Its preprint appeared in September 2005; the 1988 talk already attributes the programme to the same three authors.', ['gelfandmacphersonvilonen2005microlocal'],cls='B',literal='correct with missing hypotheses',match='partial',development='annotated',reconstruction='The twisting is a modern clarification, not wording supplied by the notebook.')
corr('P001450','Zero section in SS','add the zero section whenever the complex is nonzero','add zero covectors only over supp(F)','Scan P001450 explicitly says to add the whole zero section. A skyscraper at x has singular support only over x; the corrected basic identity is SS(F) intersect zero section = supp(F).')
corr('P001451','Lagrangian versus involutive ideal','an equivalent condition is involutivity of the ideal','involutivity plus pure dimension dim(X)','The full cotangent bundle has zero, hence involutive, defining ideal but is not Lagrangian when dim(X)>0. The notebook omits the dimension hypothesis.')
corr('P001452','Perversity degree','degree 0; parenthesis: first degree','state the cone/vanishing-cycle shift convention','Both readings occur in the scan and transcriptions. The normalized Morse relative complex is concentrated in degree 0 for C_X[dim X]; raw vanishing cycles have a shifted convention.','ambiguity')
corr('P001452','Independence of test function','the choice of f makes no difference','Morse groups are identified after normalization and Maslov data','The chosen covector does not supply a canonical untwisted identification across loops in the space of Hessians; GMV 2005 section 1 states the extra structure.')
save()

item(745,'P001453','definition','Configurations, reducibility, and unavoidability',r'A configuration is a triangulated disc; an unavoidable collection occurs in every triangulation, and a reducible member cannot occur in a smallest counterexample.',r'In a finite simple plane triangulation, a configuration specifies a finite near-triangulation together with the required degrees of its internal vertices and a boundary ring. Reducibility means that an occurrence can be replaced by a smaller graph whose four-colouring can be lifted, possibly using Kempe changes. An unavoidable set is one occurring in every triangulation of the relevant reduced class.',r'\citet[\S3]{gonthier2005fourcolour} states the established proof structure, already present in the 1977 Appel--Haken proof. An arbitrary disc triangulation without embedding and degree data is not the complete configuration specification.', ['gonthier2005fourcolour','appelhakenkoch1977reducibility'],literal='correct with missing hypotheses',reconstruction='Degree and boundary data and the relevant class of minimal counterexamples are restored.')
a=item(745,'P001453','method','An unavoidable reducible family proves four-colourability',r'The main idea is to combine the two definitions and induct on the number of vertices.',r'If every minimal non-four-colourable plane triangulation contains a member of a fixed family, and every member is reducible, no minimal counterexample exists. Every finite loopless planar graph embeds in a triangulation after the usual harmless additions, yielding the theorem.',r'The proof scheme was realized in \citet{appelhakenkoch1977reducibility}; \citet[\S3, parts I--II]{gonthier2005fourcolour} states its formalized version.', ['appelhakenkoch1977reducibility','gonthier2005fourcolour'],problem='GP-1987-43')
next(p for p in problems if p['id']=='GP-1987-43')['occurrences'].append(a)
item(745,'P001454','remark','The cosine addition identity as a spherical-function example',r'Gelfand says his spherical-function theory arose from \(\cos(\alpha+\beta)+\cos(\alpha-\beta)=2\cos\alpha\cos\beta\), using translations and reflections of the line.',r'For \(G=\mathbb R\rtimes\{\pm1\}\), \(K=\{\pm1\}\), the functions \(\varphi_t(x)=\cos(tx)\) are normalized \(K\)-bi-invariant spherical functions and satisfy \(\frac12[\varphi_t(x+y)+\varphi_t(x-y)]=\varphi_t(x)\varphi_t(y)\). This is a concrete product-formula model.',r'The general spherical-function setting is represented by \citet{berezingelfand1956spherical}; the displayed semidirect-product calculation directly verifies the specific example. The personal account of invention is not independently checked.', ['berezingelfand1956spherical'],speaker='I. M. Gelfand',match='thematic only',verification='indirect',reconstruction='The parameter t, subgroup K and normalized averaging are explicit reconstruction of the stated example.')
item(745,'P001454','theorem','Degree-four vertices are reducible by a Kempe argument',r'For four neighbours with all four colours, either the 1--3 Kempe path is absent, or its planar separation prevents a 2--4 path; a colour swap frees a colour.',r'In a plane triangulation, a vertex of degree four cannot belong to a minimal non-four-colourable graph. Remove it and colour the smaller graph. If the four cyclic neighbours use four different colours, disjoint alternating 1--3 and 2--4 connecting paths cannot both exist in the punctured plane; swap on a component of one colour pair and extend the colouring.',r'\citet[\S3, the square case]{gonthier2005fourcolour} records this classical Kempe reduction. The valid degree-four argument does not validate Kempe\textquotesingle s failed degree-five argument.', ['gonthier2005fourcolour'],reconstruction='The cyclic order and planarity are the essential topological hypotheses.',literal='correct with missing hypotheses')
item(745,'P001455','method','Boundary colourings and Kempe closure',r'Some boundary colourings extend into a configuration, others do not; a computer searches for recolourings as in the previous example.',r'For a fixed finite ring configuration, enumerate proper four-colourings of the ring and the subset extendible through the interior. Reducibility tests combine this finite data with the permitted noncrossing Kempe-chain pairing information from the exterior. Arbitrary swaps of boundary colours without such compatibility do not establish reducibility.',r'\citet[\S5.2]{gonthier2005fourcolour} formalizes the Kempe-chain and reducibility calculation. The 1977 proof already used finite reducibility algorithms; the later proof verifies a specific implementation.', ['gonthier2005fourcolour','appelhakenkoch1977reducibility'],literal='correct with missing hypotheses',match='partial',reconstruction='The exterior noncrossing compatibility, not spelled out in the sketch, is essential.')
item(745,'P001455','theorem','The drawn configuration is the Birkhoff diamond',r'The scan draws a hexagonal ring around four interior vertices and calls it reducible, adding that Fuchs could not prove it.',r'The four interior vertices span two triangles sharing an edge, and each has degree five in the completed patch. Together with the six-vertex boundary this is the free completion of the Birkhoff diamond, a reducible configuration.',r'The scan was compared with the structural description in \citet[\S3, part g, pp.~7--8]{gonthier2005fourcolour}. Its reducibility is a classical pre-1988 result, not a new unresolved problem; the attribution to the name Birkhoff is editorial.', ['gonthier2005fourcolour'],reconstruction='Identification uses the graph incidence and degree-five internal vertices visible in the scan; no missing proof is attributed to Fuchs.',confidence='medium')
a=item(745,'P001455','problem','A parallel program for a fixed reducibility test',r'Gelfand\textquotesingle s numbered problem asks for a program determining reducibility on a parallel computer.',r'Given a finite ring configuration, implement a specified sound finite reducibility test based on boundary colourings and compatible Kempe data, allowing independent colourings/configurations to be processed in parallel. No machine model, complexity bound or completeness criterion for all notions of reducibility is stated.',r'Computer reducibility tests already existed in 1977, and \citet[\S5.2]{gonthier2005fourcolour} later gives a formally checked implementation. That is only a partial match: this search did not identify a publication answering Gelfand\textquotesingle s exact parallel-program request. Finite enumeration itself can be parallelized, so the text does not define a new unsolved mathematical decision problem.', ['gonthier2005fourcolour','appelhakenkoch1977reducibility'],cls='B',literal='correct with missing hypotheses',match='partial',problem='GP-1987-45',speaker='I. M. Gelfand',confidence='medium',reconstruction='A specified finite sufficient test is distinguished from universal semantic reducibility; without that distinction the requested input/output problem is ambiguous.',status='the finite testing method and verified implementations are established; no exact historical parallel implementation has been identified.')
prob(45,'Parallel implementation of configuration reducibility tests',items[-1]['statement'],[a],r'Established finite reducibility algorithms and later verified implementations give a partial match; the exact parallel architecture and requested performance were never specified. No new complexity claim is made.',['gonthier2005fourcolour','appelhakenkoch1977reducibility'])
item(745,'P001455-P001456','theorem','Euler curvature and a first unavoidable set',r'Using \(V-E+F=2\), \(2E=\sum i\nu_i\), \(3F=2E\), the notes derive \(\sum(6-i)\nu_i=12\), so a degree-three, four or five vertex exists.',r'For a finite simple triangulation of the sphere with at least four vertices, \(\sum_v(6-\deg v)=12\). Its minimum degree is at most five. Degree-three and degree-four reduction therefore leaves minimum degree at least five in any minimal counterexample.',r'This is the Euler-counting step recalled in \citet[\S3]{gonthier2005fourcolour}. The numerical identity follows directly from the three displayed counts and does not depend on computation.', ['gonthier2005fourcolour'],literal='correct with missing hypotheses',reconstruction='Sphere topology, simplicity and the small-size exclusion justify the degree range.')
item(745,'P001456-P001457','method','Discharging preserves the total charge',r'Assign charge \(60(6-i)\) to degree i, redistribute 30 along specified edges, and seek a contradiction by making every final charge nonpositive.',r'The initial charge sum is \(720\). Any pairwise transfer conserves it. Therefore, if absence of a finite configuration family forces every final charge to be nonpositive under a fully specified set of transfer rules, that family is unavoidable. The single sample rule in the notes does not by itself prove the required universal implication.',r'\citet[\S3, discharging steps 1--2]{gonthier2005fourcolour} gives the precise proof pattern. Appel--Haken\textquotesingle s completed rule system is a much larger object than this board sketch.', ['gonthier2005fourcolour','appelhakenkoch1977reducibility'],literal='correct with missing hypotheses',match='partial',reconstruction='Conservation is exact; completeness of the discharge rules is not reconstructed from the incomplete examples.')
corr('P001457','Computer time','12,000 hours, with (1200?) below','retain the manuscript doubt; the contemporary published digest reports 1200 hours','The scan itself queries the larger figure. Bernhart 1977, publisher abstract, explicitly gives 1200 hours for nearly 1900 configurations. This is a factual emendation, not a transcription error.','ambiguity')
save()

item(746,'P001457','theorem','Zero microsupport detects local constancy',r'\(SS(F)\) equals the zero section iff all cohomology sheaves are locally constant; the whole zero section is again inserted for any nonzero complex.',r'For a constructible complex, \(SS(F)\subset T_X^*X\) iff all its cohomology sheaves are locally constant. Equality holds on connected components where the complex is nonzero. The zero complex has empty support, so equality cannot be used without the component/support qualification.',r'\citet[\S3.1]{kashiwaraschapira1985microlocal} gives the local-constancy criterion. This is a second occurrence of the support error corrected in 1987-744.3.', ['kashiwaraschapira1985microlocal'],literal='false as written',development='annotated')
item(746,'P001457-P001458','construction','Vanishing cycles as relative hypercohomology',r'Take \(f(x)=0\), \(df_x=\nu\), and compare cohomology on a small neighbourhood with a nearby nonzero fibre; relative cohomology is defined by a cone.',r'For a sufficiently small Milnor neighbourhood and a constructible complex adapted to \(f\), the relative derived sections \(R\Gamma(B,B\cap f^{-1}(\varepsilon);F)\) are the fibre of the restriction map. Equivalently they are its cone shifted by \(-1\). They describe local vanishing-cycle data, with the chosen convention recorded.',r'The microlocal construction in \citet[\S1]{gelfandmacphersonvilonen2005microlocal} uses these local Morse data. The cone shift matters for the degree-zero definition on the next line.', ['gelfandmacphersonvilonen2005microlocal','kashiwaraschapira1985microlocal'],literal='correct with missing hypotheses',reconstruction='The Milnor neighbourhood, nearby regular value and shifted-cone convention are supplied.')
item(746,'P001458','definition','Repeated microlocal characterization of perversity',r'A holomorphic Morse function has graph transverse to singular support; vanishing cycles occur in one degree and form a local system over the smooth support.',r'Use isolated transverse intersections with the smooth support, degree-zero normalized Morse groups, and the Maslov-twisted local-system construction. These are the same conditions as in 1987-744.7--744.11, not a new criterion.',r'\citet[Theorem~9.5.2]{kashiwaraschapira1985microlocal} and \citet[\S1]{gelfandmacphersonvilonen2005microlocal} supply the precise formulations.', ['kashiwaraschapira1985microlocal','gelfandmacphersonvilonen2005microlocal'],literal='correct with missing hypotheses',reconstruction='The normalization and twist from the earlier occurrence remain necessary.',match='partial')
a=item(746,'P001458-P001459','problem','Reconstruct perverse sheaves from microlocal Morse data',r'The proposed third method is a microlocal description by vanishing cycles; the report says the work solves half of the problem.',r'Let \(X\) be a complex manifold and \(\Lambda\subset T^*X\) a specified closed complex analytic conic Lagrangian. With coefficients in \(\mathbb C\), describe the category of perverse sheaves with singular support in \(\Lambda\) by local Morse data on the smooth pieces, gluing at codimension-one loci, and explicit compatibility conditions at singular loci. A complete answer must characterize the essential image, not only embed the category faithfully.',r'\citet[Theorem~5.1 and Theorem~6.4]{gelfandmacphersonvilonen2005microlocal}, first circulated on arXiv in September 2005, proves an equivalence away from the codimension-two locus and a global fully faithful embedding in melded Morse data. \citet[Theorem~1.1]{kashiwaravilonen2014codimension}, announced in 2010 with a full preprint in 2012 and publication in 2014, proves unique extension across analytic subsets of codimension at least three in the Lagrangian support. The exact remaining task is formulated as Problem~9.3 of that paper (published p.~617): describe the conditions imposed by the codimension-two locus on the essential image. The extension theorem does not erase these conditions. \citet[Introduction]{guminov2025perverse} confirms that explicit category descriptions remain available only for restricted families.', ['gelfandmacphersonvilonen2005microlocal','kashiwaravilonen2014codimension','guminov2025perverse'],cls='C',literal='correct with missing hypotheses',match='partial',problem='GP-1987-46',worth='A fixed singular support with concrete codimension-two links would make a useful bounded project, but the notebook supplies no such geometry to calculate here.',confidence='medium',reconstruction='The fixed-support categorical formulation and essential-image distinction make the informal reconstruction question precise; no arbitrary missing codimension-two formula is invented.',status='partially developed over complex coefficients in the explicit microlocal-data sense stated here. Kashiwara--Vilonen Problem 9.3 explicitly isolates the codimension-two essential-image question. The consulted later primary literature does not settle that general geometric description; this is a bounded search conclusion, not a claim that no categorical reconstruction theorem of any kind exists.')
prob(46,'Microlocal reconstruction of perverse sheaves',items[-1]['statement'],[a],r'Partial over complex coefficients: GMV 2005 proves the fully faithful embedding and the codimension-one equivalence; Kashiwara--Vilonen 2014 (announced 2010, full preprint 2012) proves extension across codimension at least three. Their Problem~9.3, p.~617, explicitly asks for the geometric codimension-two conditions on the essential image. No general solution to that remaining task was identified through 11 November 2026.',['gelfandmacphersonvilonen2005microlocal','kashiwaravilonen2014codimension','guminov2025perverse'])
item(746,'P001458','construction','Holonomic differential equations and perverse solution complexes',r'One construction uses overdetermined differential equations, a solution complex, and a Dolbeault resolution.',r'For a regular holonomic left \(\mathcal D_X\)-module on a smooth complex n-fold, the shifted derived solution complex \(R\mathcal Hom_{\mathcal D_X}(M,\mathcal O_X)[n]\) is perverse. Regular holonomic modules and complex-constructible perverse sheaves correspond contravariantly. A merely overdetermined system need not be holonomic, and an ordinary solution sheaf need not equal its derived solution complex.',r'\citet[main theorem, p.~1]{kashiwara1980constructible} announces the derived equivalence in the lecture of 22 April 1980; \citet{kashiwara1984riemann} is the full later publication. This predates the seminar.', ['kashiwara1980constructible','kashiwara1984riemann'],literal='correct with missing hypotheses',reconstruction='Regular holonomicity is used for this safe exact equivalence; the notebook does not specify the module class or solution shift.')
item(746,'P001459','construction','Intersection cohomology and intermediate extension',r'The Goresky--MacPherson combinatorial method extends sheaves to singular points and yields perverse sheaves.',r'If \(j:U\hookrightarrow X\) is a smooth dense stratum of complex dimension d and \(L\) a finite-rank local system, its perverse intermediate extension \(j_{!*}L[d]\) is the intersection-cohomology complex. Arbitrary extensions across singular strata need not be perverse or canonical.',r'The intersection-cohomology construction is \citet{goreskymacpherson1983intersection}; the extension viewpoint is also explicit in \citet{beilinson1987glue}.', ['goreskymacpherson1983intersection','beilinson1987glue'],literal='correct with missing hypotheses',verification='indirect',reconstruction='Intermediate extension is the precise reconstruction of the broad extension statement.')
corr('P001457','Zero-section equivalence',r'SS(F)=zero section iff H^i(F) locally constant',r'SS(F) is contained in the zero section iff H^i(F) locally constant; equality only on the support','The zero object is an immediate counterexample to equality. On disconnected X a nonzero locally constant complex may vanish on a component.')
save()

item(747,'P001461','theorem','The finite Morse index of a geodesic',r'The energy functional on the path space has finite negative index, equal to the number of conjugate points along the geodesic.',r'For a geodesic segment in a smooth Riemannian manifold with fixed endpoints, the Hessian of energy has finite Morse index. It equals the sum of the multiplicities of conjugate points to the initial endpoint in the open segment; conjugacy at the final endpoint contributes to nullity, not to the negative index.',r'\citet[\S\S1--3]{duistermaat1974morse} formulates the index in variational and Lagrangian terms. Boundary conditions and multiplicities, omitted in the board sentence, determine the exact result.', ['duistermaat1974morse'],literal='correct with missing hypotheses',reconstruction='Fixed endpoints and the endpoint/nullity convention are supplied.')
item(747,'P001461','method','Relative grading for strongly indefinite functionals',r'Critical points may have infinitely many positive and negative directions, but the numbers of negative directions are said to differ by a finite number; homology is counted from infinity over two.',r'For a continuous path of self-adjoint Fredholm Hessians with invertible ends and appropriate operator-domain control, spectral flow supplies a finite relative index. Infinite positive and negative indices alone do not imply that an index difference exists. A Floer complex additionally requires compactness, transversality, coherent orientation and control of broken trajectories.',r'\citet[pp.~286--294]{atiyah1988invariants} explains the gauge-theoretic Morse picture, circulated as a 1987 lecture/preprint. \citet{floer1988instanton}, received 3 May and published June 1988, establishes the associated homology-sphere invariant. This is exposition of a programme under development, not a general theorem for arbitrary functionals.', ['atiyah1988invariants','floer1988instanton'],cls='B',literal='correct with missing hypotheses',match='partial',reconstruction='The Fredholm and analytic hypotheses replace subtraction of two infinite cardinalities.',status='relative-index Floer theories are established under specific analytic hypotheses; the unrestricted formulation is invalid.')
item(747,'P001461','remark','Relation with Donaldson invariants',r'The striking claim is that these invariants are related to Donaldson invariants of four-manifolds; gauge fields and flat connections are drawn.',r'The relevant functional on three-dimensional connections is Chern--Simons: its critical points are flat connections and its cylinder gradient equation is the anti-self-dual equation in four dimensions. Donaldson theory can therefore interact with the boundary Floer groups through cutting and gluing.',r'\citet[\S\S2--5]{atiyah1988invariants} is the named source; record 751 supplies the detailed seminar continuation. The ordinary Yang--Mills energy on a three-manifold can have nonflat critical points, so the functional in the sketch must not be identified with it without correction.', ['atiyah1988invariants'],literal='correct with missing hypotheses',match='partial',reconstruction='The functional is reconstructed as Chern--Simons from the named source and later continuation; Yang--Mills criticality alone would be insufficient.')
item(748,'P001461','construction','Positive and negative Fourier polarizations on the circle',r'Gelfand recalls decomposing \(C^\infty(S^1)\) into boundary values extending inside and outside, with applications to tau-functions and semi-infinite cohomology.',r'A smooth complex function on the circle splits into its Fourier modes \(\sum_{n\geq0}a_nz^n\) and \(\sum_{n<0}a_nz^n\). With constants included in both pieces the intersection is one-dimensional; with the negative part vanishing at infinity the direct-sum convention removes that overlap. Appropriate Sobolev completions give Hardy polarizations.',r'The elementary Fourier construction verifies the concrete circle example. \citet[the loop-space discussion]{atiyah1988invariants} supplies the context of relative polarizations; no new tau-function identity is asserted.', ['atiyah1988invariants'],literal='correct with missing hypotheses',match='thematic only',reconstruction='Boundary regularity, the constant mode and the outside normalization are made explicit.')
item(748,'P001461','remark','Replacing the circle by another manifold',r'Gelfand says that remarkably the circle can be replaced by other manifolds, and postpones the explanation.',r'No definite generalization is determined without a chosen operator or polarization, coefficient bundle, function space and intended semi-infinite invariant.',r'The adjacent Atiyah discussion motivates spectral polarizations, but this sentence alone does not identify one. No missing theorem or open problem has been manufactured from it.', ['atiyah1988invariants'],cls='F',literal='not determinable',match='thematic only',verification='unresolved lead',confidence='low',status='unidentified beyond a research direction.')
save()

item(749,'P001461-P001462','definition','The rank-one quantum enveloping algebra and its completion',r'The generators \(H,X^\pm\) satisfy \([H,X^\pm]=\pm2X^\pm\) and \([X^+,X^-]=\sinh(hH/2)/\sinh(h/2)\), with \(q=e^h\); powers of both \(H\) and \(q^{H/4}\) are called a vector-space basis.',r'One coherent formulation is the h-adic algebra \(U_h(\mathfrak{sl}_2)\), topologically free over \(\mathbb C[[h]]\), with the displayed relations and PBW monomials \((X^-)^aH^b(X^+)^c\). Alternatively, for a numerical generic parameter use the algebraic Cartan generator \(K^{\pm1}\) and a PBW basis in \(X^-,K,X^+\). Exponentials are interpreted in a completion, not added as unspecified independent formal generators.',r'\citet[I, Definition~1.1 and Theorem~1.1]{reshetikhin1987quantizedi} gives this quantum-group setting. The LOMI preprint was recommended for publication on 6 June 1987, before the seminar.', ['reshetikhin1987quantizedi'],literal='correct with missing hypotheses',reconstruction='The completion and base ring are fixed explicitly; the notebook does not specify which algebra is meant by its basis.',match='partial')
item(749,'P001462','construction','The symmetric coproduct and counit',r'\(\Delta H=H\otimes1+1\otimes H\), \(\Delta X^\pm=X^\pm\otimes q^{H/4}+q^{-H/4}\otimes X^\pm\); this is an algebra homomorphism and coassociative.',r'Put \(L=e^{hH/4}\), so \(\Delta L=L\otimes L\). The displayed coproduct extends to the completed algebra, is coassociative, and has counit \(\epsilon(H)=\epsilon(X^\pm)=0\), \(\epsilon(1)=1\).',r'These formulas are \citet[I, Theorem~1.1, equations~(1.4)--(1.5)]{reshetikhin1987quantizedi}. Coassociativity on \(X\) follows by expanding both sides as \(X\otimes L\otimes L+L^{-1}\otimes X\otimes L+L^{-1}\otimes L^{-1}\otimes X\).', ['reshetikhin1987quantizedi'],literal='correct with missing hypotheses',reconstruction='All tensor products use the same h-adic completion.')
item(749,'P001462','claim','The antipode needs a minus sign and half the exponent',r'The scan states \(S(X^\pm)=q^{H/2}X^\pm q^{-H/2}\), with \(S(H)=-H\).',r'For the displayed coproduct, \(S(X^\pm)=-L X^\pm L^{-1}=-q^{\pm1/2}X^\pm\), where \(L=q^{H/4}\). Indeed \(m(S\otimes\mathrm{id})\Delta X=S(X)L+LX=0\). The source expression fails this identity and has the wrong classical limit.',r'\citet[I, Theorem~1.1, equation~(1.6), with \(\rho=H/2\)]{reshetikhin1987quantizedi} confirms the normalization. The correction is to a faithfully transcribed formula.', ['reshetikhin1987quantizedi'],literal='false as written',development='annotated',status='the corrected antipode is established; the printed one is incompatible with the printed coproduct.')
item(749,'P001462','definition','The Cartan-generator substitution changes the denominator',r'After putting \(K=q^{H/2}\), the notes keep \(KX^\pm=q^{\pm1}X^\pm K\), but write the commutator denominator \(q-q^{-1}\).',r'With the unchanged parameter \(q=e^h\), the initial relation becomes \([X^+,X^-]=(K-K^{-1})/(q^{1/2}-q^{-1/2})\). If instead the standard parameter is \(t=q^{1/2}\), then \(KX^\pm=t^{\pm2}X^\pm K\) and the denominator is \(t-t^{-1}\). A rescaling of generators is another possible convention, but must be stated.',r'Compare the fixed relation in \citet[I, equation~(1.2)]{reshetikhin1987quantizedi}. Direct substitution detects the factor mismatch.', ['reshetikhin1987quantizedi'],literal='false as written',development='annotated',reconstruction='The correction keeps the original generators and parameter; no silent rescaling is made.')
item(749,'P001463','construction','Finite-dimensional spin representations and the classical limit',r'\((X^+)^*=X^-\), \(H^*=H\), and a square-root formula is given on \(e_m^j\), with dimension \(2j+1\); Gelfand asks for the \(q=1\) limit.',r'For real \(q>0\), define \([a]=(q^{a/2}-q^{-a/2})/(q^{1/2}-q^{-1/2})\), with its limiting value at 1. For \(j\in\frac12\mathbb Z_{\geq0}\), \(m=-j,-j+1,\ldots,j\), let \(He_m=2me_m\) and \(X^\pm e_m=\sqrt{[j\mp m][j\pm m+1]}e_{m\pm1}\). These give the compact real-form spin modules and tend to the usual \(\mathfrak{su}_2\) formulas as \(q\to1\).',r'The highest-weight framework is \citet[I, Propositions~1.1--1.2]{reshetikhin1987quantizedi}; the rank-one coefficients can be checked by substitution into the relations.', ['reshetikhin1987quantizedi'],literal='correct with missing hypotheses',reconstruction='Nonnegative half-integer j, unit steps for m, and a positive real parameter for the unitary interpretation are restored.')
item(749,'P001463','question','Expanding vector fields on the sphere',r'Gelfand asks how to expand vector fields on a sphere in spherical harmonics, beginning with \(SU(2)\). The last word is partly unclear.',r'For the standard oriented round \(S^2\), a smooth tangent field is expanded in \(\nabla_{S^2}Y_{\ell m}\) and \(n\times\nabla_{S^2}Y_{\ell m}\), \(\ell\geq1\). There is no harmonic one-form term because \(H^1(S^2)=0\). For an ambient \(\mathbb R^3\)-valued field also include the radial terms \(nY_{\ell m}\). Smooth expansions converge in the smooth topology with the usual coefficient decay.',r'The scalar normalization is given in \citet[\S14.30]{nist2026dlmf}; gradient and rotated-gradient components follow from the Hodge decomposition on the sphere. This answers a classical exercise, not a new quantum-group problem.', ['nist2026dlmf'],speaker='I. M. Gelfand',literal='correct with missing hypotheses',match='partial',verification='indirect',confidence='medium',reconstruction='The standard round sphere and tangent/ambient distinction are supplied; they are not explicit in the abbreviated question.')
item(749,'P001463','claim','The universal R series needs deformation factors and a completion',r'The formula has \(R=e^{hH\otimes H/4}\sum_{n\geq0}q^n e^n\otimes f^n/[n]_q!\), with \(e=q^{H/4}X^+\), \(f=q^{-H/4}X^-\).',r'The formal quasitriangular structure has \(R\in U_h\widehat\otimes U_h\), \(R\equiv1\pmod h\), and intertwines the two coproducts. Its nth nilpotent term contains a factor vanishing to order n in h, conventionally a power of \(q^{1/2}-q^{-1/2}\). The printed series with the printed e,f cannot have the required classical limit.',r'\citet[I, Theorems~1.2--1.3]{reshetikhin1987quantizedi} and \citet[\S3]{reshetikhinturaev1990ribbon} give the quasitriangular construction. The q-exponent depends on generator conventions; this chapter does not invent an exact corrected coefficient from the abbreviated series.', ['reshetikhin1987quantizedi','reshetikhinturaev1990ribbon'],literal='false as written',match='partial',development='annotated',reconstruction='The exact missing coefficient is not guessed; only the required deformation order and completion are asserted.')
item(749,'P001463','theorem','Quasitriangular identities and the Yang--Baxter equation',r'The intertwining equation and Yang--Baxter equation are stated, but both coproduct-factor identities have their order reversed.',r'With \(\Delta^{\mathrm{op}}(a)=R\Delta(a)R^{-1}\), use \((\Delta\otimes\mathrm{id})R=R_{13}R_{23}\), \((\mathrm{id}\otimes\Delta)R=R_{13}R_{12}\). These imply \(R_{12}R_{13}R_{23}=R_{23}R_{13}R_{12}\). Opposite conventions require changing the accompanying definitions consistently.',r'The stated order is exactly \citet[I, Theorem~1.3, equations~(1.8a)--(1.8c)]{reshetikhin1987quantizedi}, also \citet[equations~(3.1.1)--(3.1.3)]{reshetikhinturaev1990ribbon}.', ['reshetikhin1987quantizedi','reshetikhinturaev1990ribbon'],literal='false as written',development='annotated',reconstruction='The correction fixes the intertwining convention already printed in the notes.')
item(749,'P001463','question','The q-gamma function',r'After the q-factorial definition Gelfand asks what \(\Gamma_q\) is.',r'For \(0<q<1\), \(\Gamma_q(z)=(1-q)^{1-z}(q;q)_\infty/(q^z;q)_\infty\), with \((a;q)_\infty=\prod_{r\geq0}(1-aq^r)\). It satisfies \(\Gamma_q(z+1)=(1-q^z)\Gamma_q(z)/(1-q)\), \(\Gamma_q(1)=1\), and tends to \(\Gamma(z)\) as \(q\uparrow1\) away from poles.',r'The standard q-gamma definition and recurrence are tabulated in \citet[\S5.18, equations~(5.18.4)--(5.18.7)]{nist2026dlmf}. The symmetric q-number in the preceding quantum algebra differs by an elementary q-power normalization.', ['nist2026dlmf'],speaker='I. M. Gelfand',reconstruction='The choice \(0<q<1\) and the nonsymmetric q-factorial convention make the exercise precise.',literal='correct with missing hypotheses')
item(749,'P001464','construction','Braiding and braid-group representations',r'\(R^{j_1j_2}=P(\pi_{j_1}\otimes\pi_{j_2})(R)\), mapping the tensor factors in the opposite order, satisfies the braid relation.',r'For finite-dimensional modules in the chosen quasitriangular category, \(c_{V,W}=P\circ(\pi_V\otimes\pi_W)(R)\) is a natural module isomorphism \(V\otimes W\to W\otimes V\). Adjacent c operators on a repeated tensor power obey the braid relations and define a braid-group representation.',r'\citet[I, \S1]{reshetikhin1987quantizedi} supplies the R-matrix framework; \citet[\S\S3--5]{reshetikhinturaev1990ribbon} formalizes the graphical functor.', ['reshetikhin1987quantizedi','reshetikhinturaev1990ribbon'],literal='correct with missing hypotheses',reconstruction='On differently coloured strands one has a coloured braid-groupoid action; an ordinary braid group acts on a fixed repeated tensor power.')
item(749,'P001464','theorem','Generic Clebsch--Gordan decomposition',r'All finite-dimensional representations are called completely reducible, and the tensor product is the classical spin sum.',r'For a generic parameter, restricted to finite-dimensional type-1 modules, \(V^{j_1}\otimes V^{j_2}\simeq\bigoplus_{r=0}^{2\min(j_1,j_2)}V^{j_1+j_2-r}\). This category is semisimple. Root-of-unity representation categories need not be semisimple, so the omitted parameter restriction changes the theorem.',r'\citet[I, Propositions~1.1--1.2 and Theorem~1.5]{reshetikhin1987quantizedi} gives the highest-weight and tensor-product setting. The seminar\textquotesingle s Clebsch--Gordan coefficients are change-of-basis matrices for this decomposition.', ['reshetikhin1987quantizedi'],literal='correct with missing hypotheses',reconstruction='Generic q and type-1 are specified, and the summation proceeds in steps of one.')
item(749,'P001464-P001466','construction','Graphical tensor calculus, duality, and ribbon structure',r'Composition joins diagrams; straight strands denote identities, crossings R and its inverse, and cups/caps have signed q-weight formulas.',r'In a rigid braided tensor category, composition and tensor product are represented by stacking and juxtaposition. Evaluation and coevaluation must satisfy the two zigzag identities; a ribbon twist supplies compatibility with framed isotopy. Explicit cup/cap coefficients depend on chosen identifications with duals and bases, particularly for half-integer spins.',r'\citet[\S\S2--5]{reshetikhinturaev1990ribbon} proves the precise ribbon-graph functor. Reshetikhin\textquotesingle s 1987-numbered LOMI preprints (1988 imprint) already present the quantum-group graphical programme. The two inconsistent-looking q-powers in the notes cannot be repaired uniquely without those basis choices.', ['reshetikhin1987quantizedi','reshetikhin1987quantizedii','reshetikhinturaev1990ribbon'],literal='correct with missing hypotheses',match='partial',reconstruction='The categorical identities are identified precisely; no unique phase normalization is inferred from the fragmentary coefficients.',confidence='medium')
item(749,'P001467','construction','The coloured link state sum and framing correction',r'Sum products of matrix entries over spin labels on elementary diagram pieces; multiply by a q-power involving under/over counts to obtain a link invariant containing Jones\textquotesingle s invariant.',r'The ribbon-category evaluation gives an invariant of coloured framed oriented links. For a blackboard-framed diagram, pass to the zero-framed version by multiplying the contribution of each component coloured by j by \(\theta_j^{-w_i}\), where \(\theta_j\) is its twist scalar and \(w_i\) its signed self-writhe, in a fixed convention. An unweighted under/over count is not the required spin-dependent twist correction. The fundamental \(\mathfrak{sl}_2\) colour yields the Jones invariant up to standard variable and normalization choices.',r'\citet[\S\S5--6]{reshetikhinturaev1990ribbon} gives the functor and link evaluation. The 1987-numbered preprint (1988 imprint) \citet{reshetikhin1987quantizedii} establishes the earlier link-invariant programme. The notebook\textquotesingle s displayed normalization is not copied as a valid formula.', ['reshetikhin1987quantizedii','reshetikhinturaev1990ribbon'],literal='false as written',match='partial',development='annotated',reconstruction='Framed versus ambient isotopy, signed self-writhe and colour-dependent twist are explicit repairs.')
item(749,'P001467','construction','Other simple Lie algebras and 6j recoupling',r'Every simple Lie algebra supplies link invariants; 6j-symbols are also mentioned.',r'For each complex simple Lie algebra at generic deformation parameter, finite-dimensional highest-weight modules and the universal R-matrix yield a family of coloured ribbon-link invariants. Associativity and chosen decompositions of triple tensor products produce quantum 6j change-of-basis matrices, with multiplicity labels when tensor products are not multiplicity-free.',r'\citet[I, Introduction and \S1]{reshetikhin1987quantizedi} states the all-simple-Lie-algebra construction before the talk. \citet[\S\S5--6]{reshetikhinturaev1990ribbon} supplies the general ribbon formulation.', ['reshetikhin1987quantizedi','reshetikhinturaev1990ribbon'],literal='correct with missing hypotheses',reconstruction='The category and multiplicity conventions are supplied; the brief 6j remark does not state a numerical formula.')
item(749,'P001467','conjecture','What does sufficiency of the SL2 invariants mean?',r'There is a conjecture that the \(SL_2\)-invariants suffice; no object or equivalence relation follows the verb.',r'If interpreted as separation of all oriented knot types by all colours of the Jones polynomial, the assertion is false. But the notes could instead mean recovery of another family of quantum invariants, or another weaker property; the exact conjecture is not recoverable.',r'\citet[Theorem~1.1]{stoimenowtanaka2008mutation} constructs infinitely many pairs of hyperbolic knots with equal coloured Jones polynomials that are not mutants. The paper records a first manuscript in December 2005 and arXiv circulation in 2006; the opened version is from 2008. This refutes the explicit separation interpretation, not every possible reading of ``suffice''.', ['stoimenowtanaka2008mutation'],cls='F',literal='not determinable',match='partial',development='annotated',reconstruction='The separation interpretation is deliberately conditional and is not entered as the original conjecture in the problem index.',confidence='medium',status='the exact statement is unidentified; the most natural complete-knot-invariant interpretation has published counterexamples.')
corr('P001462','Equation (4), antipode',r'S(X^\pm)=q^{H/2}X^\pm q^{-H/2}',r'S(X^\pm)=-q^{H/4}X^\pm q^{-H/4}','Scan verified. The displayed coproduct forces S(X)L+LX=0 for L=q^{H/4}; Reshetikhin 1987 I equation (1.6) agrees after rho=H/2.')
corr('P001462','Cartan-generator commutator',r'(K-K^{-1})/(q-q^{-1}), K=q^{H/2}',r'(K-K^{-1})/(q^{1/2}-q^{-1/2}) with the original generators','Direct substitution into P001461 gives this denominator. A different standard parameter is possible only if all q-relations are changed consistently.')
corr('P001463','Equation (8), universal R series','coefficients q^n/[n]_q! with e=q^{H/4}X+, f=q^{-H/4}X-','include the missing deformation factors and specify a completed tensor product','The scan agrees with the transcription. For h tending to 0 the displayed nonconstant terms do not vanish, contradicting R=1 modulo h; no unique full coefficient is guessed.')
corr('P001463','Equation (10), coproduct identities',r'(Delta tensor id)R=R23 R13; (id tensor Delta)R=R12 R13',r'(Delta tensor id)R=R13 R23; (id tensor Delta)R=R13 R12','With Delta-op(a)=R Delta(a) R^-1, Reshetikhin 1987 I Theorem 1.3 and RT1990 equations (3.1.2)-(3.1.3) fix this order; scan verified.')
corr('P001465','Equation (20), crossing domain/codomain',r'R^{j1 j2}:V^{j1} tensor V^{j1} to V^{j1} tensor V^{j1}',r'R^{j1 j2}:V^{j1} tensor V^{j2} to V^{j2} tensor V^{j1}','The previous definition on P001464 and the differently coloured crossing require both labels; the repeated j1 is a faithful formula slip.')
corr('P001467','Equation (31), projection correction','q raised to under/over count without colour-dependent twist','use the ribbon twist scalar for each colour and the signed self-writhe','Scan verified; a Reidemeister-I move changes ribbon evaluation by the twist of the colour, not a universal q factor. RT1990 sections5-6 gives the categorical normalization.')
